import{_ as d,o as s,c as o,a0 as e}from"./chunks/framework.0IFmVATr.js";const c=JSON.parse('{"title":"Sub-Map: ML-07-4 TUI 渲染与交互 (Stage 4: Hooks 层)","description":"","frontmatter":{},"headers":[],"relativePath":"map/sub-maps/ML-07-4.md","filePath":"map/sub-maps/ML-07-4.md"}'),r={name:"map/sub-maps/ML-07-4.md"};function i(a,t,l,n,h,u){return s(),o("div",null,[...t[0]||(t[0]=[e('<p>&lt;!-- analysis-version: 0 | commit: a5179f6 | updated: 2025-01-20 | mode: full | split-from: ML-07 | split-strategy: layer | total-segments: 5 --&gt;</p><h1 id="sub-map-ml-07-4-tui-渲染与交互-stage-4-hooks-层" tabindex="-1">Sub-Map: ML-07-4 TUI 渲染与交互 (Stage 4: Hooks 层) <a class="header-anchor" href="#sub-map-ml-07-4-tui-渲染与交互-stage-4-hooks-层" aria-label="Permalink to &quot;Sub-Map: ML-07-4 TUI 渲染与交互 (Stage 4: Hooks 层)&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Stage 4 包含 REPL 组件使用的全部 39 个自定义 hooks。这些 hooks 封装了从快捷键处理、会话管理到网络轮询等各类副作用逻辑，是 REPL.tsx 编排能力的核心支撑层。</p><h3 id="hooks-分类" tabindex="-1">Hooks 分类 <a class="header-anchor" href="#hooks-分类" aria-label="Permalink to &quot;Hooks 分类&quot;">​</a></h3><p><strong>会话管理 Hooks</strong>:</p><ul><li>useReplBridge: 核心查询桥接，连接 REPL UI 与 QueryEngine</li><li>useRemoteSession: 远程会话管理</li><li>useDirectConnect: 直连模式</li><li>useSSHSession: SSH 会话</li></ul><p><strong>快捷键 Hooks</strong>:</p><ul><li>useGlobalKeybindings: 全局快捷键注册</li><li>useCommandKeybindings: 命令模式快捷键</li><li>useCancelRequest: 请求取消处理</li></ul><p><strong>网络/轮询 Hooks</strong>:</p><ul><li>useInboxPoller: 收件箱轮询 + 权限轮询</li><li>useSwarmPermissionPoller: Swarm 权限轮询</li></ul><p><strong>UI 状态 Hooks</strong>:</p><ul><li>useSearchInput: 搜索输入管理</li><li>useAssistantHistory: 历史记录</li><li>useSessionBackgrounding: 会话后台管理</li><li>useBackgroundTaskNavigation: 后台任务导航</li></ul><p><strong>工具/集成 Hooks</strong>:</p><ul><li>useManagePlugins: 插件管理</li><li>useTasksV2: 任务系统 V2</li><li>useIdeSelection: IDE 选区</li><li>useIDEIntegration: IDE 集成</li></ul><h2 id="files-traced" tabindex="-1">Files Traced <a class="header-anchor" href="#files-traced" aria-label="Permalink to &quot;Files Traced&quot;">​</a></h2><h3 id="core-hooks" tabindex="-1">Core Hooks <a class="header-anchor" href="#core-hooks" aria-label="Permalink to &quot;Core Hooks&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>File</th><th>Role</th><th>Lines</th><th>Key Symbols</th></tr></thead><tbody><tr><td>1</td><td>src/hooks/useGlobalKeybindings.ts</td><td>全局快捷键注册：Escape/ctrl+c/ctrl+z/ctrl+o 等</td><td>249</td><td>useGlobalKeybindings()</td></tr><tr><td>2</td><td>src/hooks/useReplBridge.tsx</td><td>核心查询桥接 hook：连接 REPL UI 与 QueryEngine 主循环</td><td>723</td><td>useReplBridge()</td></tr><tr><td>3</td><td>src/hooks/useRemoteSession.ts</td><td>远程会话管理 hook：WebSocket 连接 + 状态同步</td><td>605</td><td>useRemoteSession()</td></tr><tr><td>4</td><td>src/hooks/useInboxPoller.ts</td><td>收件箱轮询 hook：轮询新消息 + 权限请求 + Swarm 通知</td><td>969</td><td>useInboxPoller()</td></tr><tr><td>5</td><td>src/hooks/useSwarmPermissionPoller.ts</td><td>Swarm 权限轮询 hook</td><td>330</td><td>useSwarmPermissionPoller()</td></tr></tbody></table><h3 id="supporting-hooks" tabindex="-1">Supporting Hooks <a class="header-anchor" href="#supporting-hooks" aria-label="Permalink to &quot;Supporting Hooks&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>File</th><th>Role</th><th>Lines</th><th>Called By</th></tr></thead><tbody><tr><td>1</td><td>src/hooks/useCommandKeybindings.ts</td><td>命令模式快捷键：slash 命令触发</td><td>108</td><td>REPL.tsx</td></tr><tr><td>2</td><td>src/hooks/useCancelRequest.ts</td><td>请求取消 hook：AbortController 管理</td><td>276</td><td>REPL.tsx</td></tr><tr><td>3</td><td>src/hooks/useQueueProcessor.ts</td><td>队列处理器 hook：dialog 队列顺序处理</td><td>68</td><td>REPL.tsx</td></tr><tr><td>4</td><td>src/hooks/useTerminalSize.ts</td><td>终端尺寸 hook：监听窗口变化</td><td>15</td><td>REPL.tsx</td></tr><tr><td>5</td><td>src/hooks/useSearchInput.ts</td><td>搜索输入 hook：搜索状态+导航+匹配计数</td><td>364</td><td>REPL.tsx</td></tr><tr><td>6</td><td>src/hooks/useMainLoopModel.ts</td><td>主循环模型 hook：获取 QueryEngine 实例</td><td>34</td><td>REPL.tsx</td></tr><tr><td>7</td><td>src/hooks/useMergedClients.ts</td><td>合并客户端 hook：本地+远程 client 合并</td><td>23</td><td>REPL.tsx</td></tr><tr><td>8</td><td>src/hooks/useMergedTools.ts</td><td>合并工具 hook：本地+MCP 工具合并</td><td>44</td><td>REPL.tsx</td></tr><tr><td>9</td><td>src/hooks/useMergedCommands.ts</td><td>合并命令 hook</td><td>15</td><td>REPL.tsx</td></tr><tr><td>10</td><td>src/hooks/useTasksV2.ts</td><td>任务系统 V2 hook：任务创建+状态+折叠</td><td>250</td><td>REPL.tsx</td></tr><tr><td>11</td><td>src/hooks/useManagePlugins.ts</td><td>插件管理 hook：MCP server CRUD</td><td>304</td><td>REPL.tsx</td></tr><tr><td>12</td><td>src/hooks/useSSHSession.ts</td><td>SSH 会话 hook：SSH transport 管理</td><td>241</td><td>REPL.tsx</td></tr><tr><td>13</td><td>src/hooks/useDirectConnect.ts</td><td>直连 hook：HTTP transport 管理</td><td>229</td><td>REPL.tsx</td></tr><tr><td>14</td><td>src/hooks/useAssistantHistory.ts</td><td>历史记录 hook：加载+导航历史会话</td><td>250</td><td>REPL.tsx</td></tr><tr><td>15</td><td>src/hooks/useSessionBackgrounding.ts</td><td>会话后台管理 hook：SIGTSTP/SIGCONT 处理</td><td>158</td><td>REPL.tsx</td></tr><tr><td>16</td><td>src/hooks/useMailboxBridge.ts</td><td>邮箱桥接 hook：Swarm mailbox 消息转发</td><td>21</td><td>REPL.tsx</td></tr><tr><td>17</td><td>src/hooks/useBackgroundTaskNavigation.ts</td><td>后台任务导航 hook：任务间切换</td><td>251</td><td>REPL.tsx</td></tr><tr><td>18</td><td>src/hooks/useSkillsChange.ts</td><td>技能文件变更 hook：监听 skill 文件更新</td><td>62</td><td>REPL.tsx</td></tr><tr><td>19</td><td>src/hooks/useCommandQueue.ts</td><td>命令队列 hook</td><td>15</td><td>REPL.tsx</td></tr><tr><td>20</td><td>src/hooks/useTaskListWatcher.ts</td><td>任务列表观察 hook：监听任务状态变化</td><td>221</td><td>REPL.tsx</td></tr><tr><td>21</td><td>src/hooks/useSwarmInitialization.ts</td><td>Swarm 初始化 hook</td><td>81</td><td>REPL.tsx</td></tr><tr><td>22</td><td>src/hooks/useCanUseTool.tsx</td><td>工具权限检查 hook</td><td>204</td><td>REPL.tsx</td></tr><tr><td>23</td><td>src/hooks/useIdeSelection.ts</td><td>IDE 选区 hook：获取编辑器当前选区</td><td>150</td><td>REPL.tsx</td></tr><tr><td>24</td><td>src/hooks/useIDEIntegration.ts</td><td>IDE 集成 hook：IDE 通信</td><td>70</td><td>REPL.tsx</td></tr><tr><td>25</td><td>src/hooks/useIdeLogging.ts</td><td>IDE 日志 hook：结构化日志</td><td>41</td><td>REPL.tsx</td></tr><tr><td>26</td><td>src/hooks/useApiKeyVerification.ts</td><td>API Key 验证 hook</td><td>84</td><td>REPL.tsx</td></tr><tr><td>27</td><td>src/hooks/useAfterFirstRender.ts</td><td>首次渲染后 hook</td><td>17</td><td>REPL.tsx</td></tr><tr><td>28</td><td>src/hooks/useDeferredHookMessages.ts</td><td>延迟 hook 消息 hook</td><td>46</td><td>REPL.tsx</td></tr><tr><td>29</td><td>src/hooks/useFileHistorySnapshotInit.ts</td><td>文件历史快照初始化 hook</td><td>25</td><td>REPL.tsx</td></tr><tr><td>30</td><td>src/hooks/useAwaySummary.ts</td><td>离开摘要 hook：生成离开期间的摘要</td><td>125</td><td>REPL.tsx</td></tr><tr><td>31</td><td>src/hooks/useSkillImprovementSurvey.ts</td><td>技能改进调查 hook</td><td>105</td><td>REPL.tsx</td></tr><tr><td>32</td><td>src/hooks/useLogMessages.ts</td><td>日志消息 hook：系统日志渲染</td><td>119</td><td>REPL.tsx</td></tr><tr><td>33</td><td>src/hooks/useIssueFlagBanner.ts</td><td>问题标记 banner hook</td><td>133</td><td>REPL.tsx</td></tr><tr><td>34</td><td>src/hooks/useTeammateViewAutoExit.ts</td><td>团队成员视图自动退出 hook</td><td>63</td><td>REPL.tsx</td></tr></tbody></table><h3 id="key-hook-details" tabindex="-1">Key Hook Details <a class="header-anchor" href="#key-hook-details" aria-label="Permalink to &quot;Key Hook Details&quot;">​</a></h3><p><strong>useReplBridge.tsx</strong> (723 lines):</p><ul><li>核心查询桥接 hook，连接 REPL UI 与 QueryEngine</li><li>管理 submit 流程：构建 UserMessage → 调用 QueryEngine.submit()</li><li>处理流式响应：监听 onAssistantMessage/onToolUse/onToolResult 回调</li><li>管理中断：AbortController 集成</li><li>返回 onSubmit/onCancel/getIsLoading/setMessages 等 API</li></ul><p><strong>useInboxPoller.ts</strong> (969 lines):</p><ul><li>收件箱轮询：周期性检查新消息（Swarm inbox）</li><li>权限轮询：检查待处理的权限请求</li><li>合并轮询：统一 setInterval 管理</li><li>消息合并：新消息追加到 messages 数组</li><li>支持暂停/恢复（transcript 模式暂停）</li></ul><p><strong>useRemoteSession.ts</strong> (605 lines):</p><ul><li>WebSocket 连接管理</li><li>远程会话状态同步</li><li>输入转发：本地输入 → 远程 QueryEngine</li><li>消息接收：远程响应 → 本地渲染</li></ul><p><strong>useGlobalKeybindings.ts</strong> (249 lines):</p><ul><li>ink useInput 的封装</li><li>注册全局快捷键映射表</li><li>处理 Escape/ctrl+c/ctrl+z/ctrl+o/ctrl+r 等</li><li>支持 conditional activation（仅在特定状态下响应）</li></ul><h2 id="cross-references" tabindex="-1">Cross-References <a class="header-anchor" href="#cross-references" aria-label="Permalink to &quot;Cross-References&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>This Main Line Role</th><th>Other Main Line(s)</th></tr></thead><tbody><tr><td>src/hooks/useCanUseTool.tsx</td><td>工具权限检查</td><td>ML-03 (工具系统) + ML-04 (权限系统)</td></tr></tbody></table><h2 id="branch-lines" tabindex="-1">Branch Lines <a class="header-anchor" href="#branch-lines" aria-label="Permalink to &quot;Branch Lines&quot;">​</a></h2><p>(本段无独立 BL — 所有 hook 的分支都是对其他 ML 的引用)</p><h2 id="pattern-instances-pi-03-react-hook-representative" tabindex="-1">Pattern Instances (PI-03 react-hook representative) <a class="header-anchor" href="#pattern-instances-pi-03-react-hook-representative" aria-label="Permalink to &quot;Pattern Instances (PI-03 react-hook representative)&quot;">​</a></h2><p>useReplBridge.tsx (723 lines) 作为 PI-03 (react-hook, 80 files) 的代表文件。 ScrollBox.tsx (237 lines) 作为 PI-07 (ink-fork-component, 100 files) 的代表文件。</p><p>其余 hook 实例（PI-03 中除 useTypeahead.tsx/useVoice.ts 外的 76 个）和 ink-fork 组件实例（PI-07 中除 ink.tsx/screen.ts/render-node-to-output.ts 外的 97 个）在 instance-manifest.jsonl 中以 catalog 模式记录。</p><h2 id="main-line-summary" tabindex="-1">Main Line Summary <a class="header-anchor" href="#main-line-summary" aria-label="Permalink to &quot;Main Line Summary&quot;">​</a></h2><ul><li>Total files traced: 39 (core: 5, supporting: 34)</li><li>Total ML lines (DEEP): 7,088</li><li>Branch lines discovered: 0</li><li>Entry → Exit: REPL.tsx 调用 30+ hooks → hooks 封装副作用 → 返回状态和回调给组件</li><li>Key architectural insight: Hooks 层是 REPL.tsx 编排能力的真正载体。useReplBridge (723行) 和 useInboxPoller (969行) 是两个最复杂的 hook，它们将 QueryEngine 交互、消息桥接和轮询逻辑完全封装，使得 REPL.tsx 虽然有 5061 行但大部分是&quot;胶水代码&quot;。39 个 hooks 的平均体积为 182 行，符合 React hook 最佳实践的&quot;单一职责&quot;原则。</li></ul>',38)])])}const p=d(r,[["render",i]]);export{c as __pageData,p as default};
